import { ISessionManagementRestrictionTranslations, ISessionStatus } from '../../types';
import { Component, Inject, Prop, Vue } from 'vue-property-decorator';
import PrimaryPopup from '../primary-popup/index.vue';

@Component({
    components: { PrimaryPopup }
})
export default class RestrictionComponent extends Vue {
    @Prop()
    public readonly closeMethod: () => any;

    @Prop()
    public readonly translations: ISessionManagementRestrictionTranslations;

    @Prop()
    public readonly sessionStatus: ISessionStatus;

    @Prop()
    public readonly sessionDuration: number;

    @Prop()
    public readonly externalPageNavigation: (url: string) => void;

    @Prop()
    public suppressed: boolean;

    @Inject()
    public readonly stringifyTime: (seconds: number) => string;

    get visible(): boolean {
        if (this.sessionStatus.SessionEnded && this.sessionStatus.SessionRestriction > 0) {
            if (this.sessionDuration - this.sessionStatus.SessionEndTime < this.sessionStatus.SessionRestriction) {
                return !this.suppressed && true;
            }
        }

        return false;
    }

    get expiryString(): string {
        return this.translations.expires.replace('${time}', this.sessionRestrictionTimeInMinutes);
    }

    get sessionRestrictionTimeInMinutes(): string {
        return this.stringifyTime(((this.sessionStatus.SessionEndTime + this.sessionStatus.SessionRestriction) - this.sessionDuration));
    }

    public itemClicked(linkAddress: string): void {
        this.externalPageNavigation(linkAddress);
    }
}